function countWords(text) {
  const counts = {};
  const words = text.toLowerCase().split(/\s+/);
  for (const word of words) {
    if (!word) continue;
    // Remove punctuation from the word
    const cleanWord = word.replace(/[^\w]/g, '');
    if (cleanWord) {
      counts[cleanWord] = (counts[cleanWord] || 0) + 1;
    }
  }
  return counts;
}"}

